  } catch (error) {
    const detail = error instanceof Error ? error.message : String(error);
    fail(`Cannot read input file: ${detail}`);
  }

  let input: unknown;
  try {
    input = JSON.parse(source);
  } catch (error) {
    const detail = error instanceof Error ? error.message : String(error);
    fail(`Invalid JSON: ${detail}`);
  }

  console.log(JSON.stringify(plan(parseTasks(input))));
}

